    queryRunner: QueryRunner,
): Promise<Migration[]> {
    if (this.connection.driver.options.type === "mongodb") {
        const mongoRunner = queryRunner as MongoQueryRunner
        return mongoRunner
            .cursor(this.migrationsTableName, {})
            .sort({ _id: -1 })
